::cw::dialog::DialogPresentation ProgressDialog::dialog_presentation()
{
    // モデルのスナップショット取得前に版を読む。同時更新はこのスナップショットに入るか、 state_revision
    // が新しいまま残って次の更新を要求するかのどちらかとなる。
    m_presented_revision.store(m_state_revision.load(std::memory_order_acquire),
                               std::memory_order_release);
    const auto state = snapshot();
    S title_text;
    I width{};
    {
        std::lock_guard lock(m_state_mutex);
        title_text = m_title;
        width = m_width_noscale + (m_cancelable ? 20 : 0);
    }
    return make_progress_presentation(dialog_retained_surface(),
        state, title_text, width, state.cancelable ? 94 : 60, false);
}

void ProgressDialog::dialog_presentation_action(
    const ::cw::dialog::DialogPresentationAction action, const int index)
{
    (void)index;
    if (action == ::cw::dialog::DialogPresentationAction::Cancel) request_cancel();
}
void ProgressDialog::dialog_presentation_key(::cw::dialog::DialogPresentationKey key,
    bool pressed,::cw::dialog::DialogPresentationModifiers modifiers)
{
    progress_key(*this,key,pressed,modifiers);
}
void ProgressDialog::dialog_presentation_enter(::cw::dialog::DialogPresentationModifiers modifiers)
{
    dialog_presentation_key(::cw::dialog::DialogPresentationKey::Enter,true,modifiers);
}

bool ProgressDialog::dialog_presentation_finished() const noexcept
{
    std::function<bool()> completion;
    {
        std::lock_guard lock(m_state_mutex);
        if(m_closed)return true;
        completion=m_completion_predicate;
    }
    try{return completion&&completion();}catch(...){return true;}
}
bool ProgressDialog::dialog_presentation_needs_refresh() const noexcept
{
    return DialogPresentationProvider::dialog_presentation_needs_refresh() ||
        m_state_revision.load(std::memory_order_acquire) !=
            m_presented_revision.load(std::memory_order_acquire);
}
void ProgressDialog::dialog_presentation_complete()
{
    close();
    clear_transient_dialog_presentation(this);
}

::cw::dialog::DialogPresentation SysProgressDialog::dialog_presentation()
{
    m_presented_revision.store(m_state_revision.load(std::memory_order_acquire),
                               std::memory_order_release);
    const auto state = snapshot();
    S title_text;
    I width{};
    {
        std::lock_guard lock(m_state_mutex);
        title_text = m_title;
        width = m_width + 20;
    }
    return make_progress_presentation(dialog_retained_surface(),
        state, title_text, width, state.cancelable ? 95 : 80, true, system_metrics());
}

void SysProgressDialog::dialog_presentation_action(
    const ::cw::dialog::DialogPresentationAction action, const int index)
{
    (void)index;
    if (action == ::cw::dialog::DialogPresentationAction::Cancel) request_cancel();
}
void SysProgressDialog::dialog_presentation_key(::cw::dialog::DialogPresentationKey key,
    bool pressed,::cw::dialog::DialogPresentationModifiers modifiers)
{
    progress_key(*this,key,pressed,modifiers);
}
void SysProgressDialog::dialog_presentation_enter(::cw::dialog::DialogPresentationModifiers modifiers)
{
    dialog_presentation_key(::cw::dialog::DialogPresentationKey::Enter,true,modifiers);
}

bool SysProgressDialog::dialog_presentation_finished() const noexcept
{
    std::function<bool()> completion;
    {
        std::lock_guard lock(m_state_mutex);
        if(m_closed)return true;
        completion=m_completion_predicate;
    }
    try{return completion&&completion();}catch(...){return true;}
}
bool SysProgressDialog::dialog_presentation_needs_refresh() const noexcept
{
    return DialogPresentationProvider::dialog_presentation_needs_refresh() ||
        m_state_revision.load(std::memory_order_acquire) !=
            m_presented_revision.load(std::memory_order_acquire);
}
void SysProgressDialog::dialog_presentation_complete()
{
    // ProgressDialog と同様、描画面だけでなくモデルも終了する
    // 。 遅れたワーカー更新やキャンセルで、完了済みの表示を復活させない。
    close();
}

namespace {
template<typename Dialog>
bool run_modal_task_impl(const std::shared_ptr<Dialog>& dialog, ProgressWork work)
{
    if (!dialog || !work) return false;
    struct Task {
        std::atomic<bool> done{false};
        std::mutex mutex;
        bool started{};
        bool retired{};
        ::cw::lib::ExceptionPtr failure;
        std::thread worker;
    };
    auto task=std::make_shared<Task>();
    const std::weak_ptr<Dialog> weak=dialog;
    struct Finish {
        std::shared_ptr<Dialog> dialog;
        std::shared_ptr<Task> task;
        ~Finish() {
            {std::lock_guard lock(task->mutex);task->retired=true;}
            dialog->set_modal_callbacks({},{});
            if(task->worker.joinable()) task->worker.join();
            dialog->close();
        }
    } finish{dialog,task};
    dialog->set_modal_callbacks([task,weak,work=std::move(work)] {
        std::lock_guard lock(task->mutex);
        if(task->retired) return true;
        const bool first_poll=!task->started;
        if(!task->started) {
            task->started=true;
            try {
                task->worker=std::thread([task,weak,work] {
                    try {
                        work([weak](::cw::lib::Integer value,::cw::lib::String message) {
                            if(const auto current=weak.lock()) current->UpdateProgress(value,std::move(message));
                        });
                    } catch(...) {task->failure=::cw::lib::capture_exception();}
                    task->done.store(true,std::memory_order_release);
                });
            } catch(...) {
                task->failure=::cw::lib::capture_exception();
                task->done.store(true,std::memory_order_release);
            }
        }
        // ネイティブホストはウィンドウを開く前に完了を確認する。 すぐ終わ
        // る処理でも ConstructScenarioDB と同様に初
        // 回の表示を許可し、成功した処理が起動失敗に見えないようにする。
        return !first_poll && task->done.load(std::memory_order_acquire);
    },{});
    const bool shown=::cw::dialog::show_common_modal_presentation(dialog);
    {std::lock_guard lock(task->mutex);task->retired=true;}
    // ホストの終了・失敗時も、ワーカーに呼び出し元の変換器・アクセス権・ミュー
    // テックスへの参照を残さない。 結果を公開する前にワーカーの終了を待つ。
    if(task->worker.joinable()) task->worker.join();
    if(task->failure) ::cw::lib::rethrow_exception(task->failure);
    return shown && task->started;
}

} // namespace

bool run_modal_task(const std::shared_ptr<ProgressDialog>& dialog, ProgressWork work)
{
    return run_modal_task_impl(dialog,std::move(work));
}
bool run_modal_task(const std::shared_ptr<SysProgressDialog>& dialog, ProgressWork work)
{
    return run_modal_task_impl(dialog,std::move(work));
}

